import itertools
for B,J,C,D,E,S,V in itertools.product((0,1), repeat=7):
 if all((not a or b) for a,b in [(J,E),(S,not B),(V,not D),(not J,C),(B,V),(V,C),(E,not C),(V,B),(D,S),(not J,D)]): print(B,J,C,D,E,S,V)
PY"

